"""Finalize verified receipts and concise interpretation; no inference."""
import csv,hashlib,json,time
from pathlib import Path
import numpy as np
OUT=Path(__file__).resolve().parent

def main():
    budget=json.loads((OUT/'budget.json').read_text());assert time.time()<budget['deadline_unix']
    v=json.loads((OUT/'verification.json').read_text());m=json.loads((OUT/'model_replay_verification.json').read_text());assert v['verified'] and m['model_parameters_immutable']
    rows=list(csv.DictReader((OUT/'data/paired_causal_effects.csv').open()));binding=[r for r in rows if r['task']=='spatial_binding' and r['condition']!='sham'];assert all(float(r['response_flip_rate'])==0 for r in binding)
    control=[]
    for site in ['cued','foil','background']:
        rr=[r for r in rows if r['task']=='orientation_cued' and r.get('site')==site]
        control.append(dict(site=site,conditions=len(rr),conditions_with_any_choice_flip=sum(float(r['response_flip_rate'])>0 for r in rr)))
    cal=json.loads((OUT/'calibration.json').read_text());a=np.load(OUT/'data/calibration.npz');achieved=[json.loads(l) for l in (OUT/'data/achieved_interventions.jsonl').read_text().splitlines()]
    errors=[]
    for r in achieved:
        if not r['condition'].startswith('stimulate'):continue
        dose=abs(float(r['condition'].split('_')[3]));nz=[e for e in r['effects'] if e['delta_rms']>0];assert len(nz)==1
        errors.append(abs(nz[0]['local_delta_rms']-cal['activation_rms']*dose))
    assert max(errors)<1e-6
    pulse=dict(feature_direction_channel_rms=float(np.sqrt(np.mean(a['direction']**2))),random_direction_channel_rms=float(np.sqrt(np.mean(a['random_direction']**2))),direction_dot_random=float(a['direction']@a['random_direction']),max_achieved_local_rms_error=max(errors),achieved_intervention_chunk_records=len(achieved),one_nonzero_update_per_pulse_verified=True)
    (OUT/'pulse_verification.json').write_text(json.dumps(pulse,indent=2))
    extra='''\n## Final interpretation and audit additions\n- Native signed-cue orientation and binding remain perfect at D0/4/12/24 in this128-per-cell sample; native ring D0 is perfect. Contour is126/128. The ring long-delay results are supplemental OOD, not part of trained-condition competence.\n- At15/30/45 degrees, all128 matched cue pairs have both requested reports correct;80/128 pairs change the correct class and the observer follows that reassignment. This supports cue-conditioned evidence use, not a cue-validity benefit. The −.25 aggregate positive-response shift reflects changed report-label frequencies. Loglinear-corrected d-prime/criterion differences in the matched-cue CSV can arise solely from changed class denominators at ceiling and are not evidence of altered sensitivity/bias.\n- The finest beta target-minus-foil contrast is exactly0 at late pure blank frame14 for both heads and both primary tasks. At encoding, cued-orientation beta contrasts are+.0186 and+.0223, with95% intervals spanning0. This does not show sustained finest-gate spatial prioritization. Finest gates depend on the current frame stack, not directly on that KDA module's stored state; flat gates do not imply absent memory. Signed source2-to-final coefficients also have target-minus-foil intervals spanning0 at all three scales/heads (16native D12 trials).\n- Cued-orientation choice flips occur in16/30 cued-site,2/30 foil-site and0/30 background-site conditions. This is a descriptive count across dependent conditions, not30independent experiments or a significance test. Largest accuracy loss is4/64trials; no universal enhancement or multiplicity-corrected causal-selection claim is justified.\n- Binding has0/64choice flips in each of24active intervention conditions. Each cell's95% Wilson upper flip-probability bound is5.6624%; zero-width paired bootstrap bars do not prove invariance. Confidence does move slightly in several cells; the table preserves continuous probability effects.\n- Emission-substrate verification measured an unchanged finest KDA state(max difference0), a changed encoding emission(max difference2.3291), and downstream final-state propagation(max difference.2568). CPU replay agrees with saved MPS logits within3.46e-6.\n- Full accelerator exposure is14,556presentations /210,438frames, including profiling, parity, calibration and repeated map extraction;14,336are scored experimental presentations. These are not14,556independent base scenes. Additional post-run CPU verification used4presentations and is recorded separately.\n- Inference completed in147.55seconds and its worker is released(PID65967 is an unreaped defunct entry, not running). Two plotting failures were repaired using the existing saved data (floating-point Wilson error-bar roundoff; duplicate summary-key merge); no inference restart or deadline renewal occurred. The browser tool could not use the non-Chromium default profile; isolated headless Chrome successfully rendered the actual file://viewer, populated trial3/frame14 and emitted a screenshot/DOM, then needed bounded shutdown termination. This is disclosed inverification.json.\n- Remaining omissions are unchanged: no independently factorialized foil sweep, no magnitude-conditioned/matched-cue allocation maps, no binding random-direction pulses, no recognition supplement; classical cue validity and reaction time are undefined for this protocol.\n'''
    p=OUT/'FINDINGS.md';text=p.read_text().split('\n## Final interpretation and audit additions')[0];p.write_text(text+extra)
    readme=OUT/'README.md';text=readme.read_text().split('\n## Final verification')[0];readme.write_text(text+'\n## Final verification\n`verification.json` checks every scored row, full paired-condition coverage, map axes, mask equality, PDF pages and the actual offline viewer. `model_replay_verification.json` checks CPU replay and untouched finest stored state with downstream propagation. `pulse_verification.json` checks achieved calibrated RMS and one-update timing. `exposure_audit.json` counts all accelerator presentations, including parity calls. `checks/viewer_screenshot.png` is an actual standalone-browser capture. No accelerator worker remains.\n\nReproduce reporting from saved data with `python3 .../render.py`, then `python3 .../verify.py`; optional CPU-only substrate replay uses the torch interpreter with `-m SecondPass.SpatialReadout.NeuroscienceAnalysis.verify_model`. `python3 .../finalize.py` writes the final audit notes/manifest. Original deadline guards intentionally prevent unapproved execution after expiry. Browser runtime shutdown warnings do not invalidate the verified DOM/screenshot.\n')
    completion=json.loads((OUT/'completion.json').read_text());completion.update(artifacts_verified=True,viewer_verified=True,pdf_pages=v['pdf_pages'],worker_released=True,total_accelerator_exposure=json.loads((OUT/'exposure_audit.json').read_text()),post_run_cpu_verification_presentations=4,pulse_verified=True,rendering_recovered_without_inference_restart=True,verification_complete_unix=time.time(),elapsed_through_verification_seconds=time.time()-budget['start_unix'],completed_within_cap=time.time()<budget['deadline_unix'])
    (OUT/'completion.json').write_text(json.dumps(completion,indent=2))
    manifest=[]
    for p in sorted(OUT.rglob('*')):
        if not p.is_file() or '__pycache__' in str(p) or '.pytest_cache' in str(p) or p.suffix=='.log' or p.name in ['artifact_manifest.json','progress.jsonl','worker.lock']:continue
        manifest.append(dict(path=str(p.relative_to(OUT)),bytes=p.stat().st_size,sha256=hashlib.sha256(p.read_bytes()).hexdigest()))
    (OUT/'artifact_manifest.json').write_text(json.dumps(manifest,indent=2))
    # Read-back exact current targets; excludes manifest self-reference.
    assert all(hashlib.sha256((OUT/r['path']).read_bytes()).hexdigest()==r['sha256'] for r in manifest)
    print(json.dumps(dict(files_hashed_and_verified=len(manifest),scored_rows=completion['scored_rows'],figures=completion['figure_count'],within_cap=completion['completed_within_cap'],elapsed_seconds=completion['elapsed_through_verification_seconds'],relative_site_choice_flip_summary=control,pulse=pulse),indent=2))

if __name__=='__main__':main()
